export const JUZ_START_PAGES: number[] = [1, 22, 42, 62, 82, 102, 121, 142, 162, 182, 201, 222, 242, 262, 282, 302, 322, 342, 362, 382, 402, 422, 442, 462, 482, 502, 522, 542, 562, 582];

export function getSurahById(id: number): SurahMeta | undefined {
  return SURAHS.find((s) => s.id === id);
}

export function getJuzForPage(page: number): number {
  let juz = 1;
  for (let i = 0; i < JUZ_START_PAGES.length; i++) {
    if (page >= JUZ_START_PAGES[i]) juz = i + 1;
  }
  return juz;
}

export function getSurahsOnPage(page: number): SurahMeta[] {
  return (PAGE_SURAHS[page] ?? [])
    .map((id) => getSurahById(id))
    .filter((s): s is SurahMeta => Boolean(s));
}
